class NotificadorEmail:
    def enviar(self, msg): return f"Email: {msg}"

class NotificadorSMS:
    def enviar(self, msg): return f"SMS: {msg}"

def obtener_notificador(canal: str):
    canales = {"email": NotificadorEmail, "sms": NotificadorSMS}
    clase = canales.get(canal.lower())
    if not clase:
        raise ValueError(f"Canal desconocido: {canal}")
    return clase()

servicio = obtener_notificador("email")
print(servicio.enviar("¡Bienvenido al nivel avanzado!"))
